from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class HealthStatus(BaseModel):
    status: str
    version: str

@app.get('/health', response_model=HealthStatus)
def health_check():
    return {'status': 'healthy', 'version': '1.0.0'}
