import React, { useState } from 'react';

export default function GoalCard({ onSubmit }) {
  const [goal, setGoal] = useState('');

  return (
    <div className='p-4 border rounded-lg bg-slate-900 text-white'>
      <textarea 
        value={goal} 
        onChange={(e) => setGoal(e.target.value)} 
        placeholder='Enter goal...' 
        className='w-full p-2 bg-slate-950 rounded border border-slate-800'
      />
      <button 
        onClick={() => onSubmit(goal)} 
        className='mt-2 px-4 py-2 bg-indigo-600 rounded text-sm font-semibold hover:bg-indigo-500'
      >
        Submit Goal
      </button>
    </div>
  );
}
